#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

int countDistinctSubsequences(string s) {
    int n = s.length();
    vector<long long> dp(n + 1, 0);
    dp[0] = 1;
    for (int i = 1; i <= n; i++) {
        dp[i] = 2 * dp[i - 1];
        dp[i] = (dp[i] - (i - 1) * dp[i - 1] + 1000000007) % 1000000007;
    }
    return (dp[n] - 1 + 1000000007) % 1000000007;
}

int main() {
    string s = "abc";
    cout << countDistinctSubsequences(s) << endl;
    return 0;
}
